-- =========================================================
-- ARCHIE SELF-EVOLVING VOCABULARY (owner directive,
-- 2026-09-13): frelux_vocabulary registry + seeded English
-- foundation (1615 entries).
--
-- The registry is ARCHIE's living language memory:
--   * seeded foundation: words, abbreviations, phrases,
--     idioms, Nigerian English — all with real meanings,
--     provenance 'seed', confidence 0.9
--   * conversation capture: unknown words the owner uses are
--     registered automatically with usage provenance,
--     meaning NULL until taught or researched (never guessed)
--   * owner-taught meanings: provenance 'owner taught in
--     chat', confidence 0.9
--
-- The typo corrector treats every registered term as known
-- (never a correction target), and persistence hydrates
-- terms WITH meanings as subject+means facts so definitions
-- answer through the honest knowledge path with provenance.
-- RLS: service role only (edge functions); no anon or
-- authenticated access.
-- =========================================================

CREATE TABLE IF NOT EXISTS public.frelux_vocabulary (
  id uuid primary key default gen_random_uuid(),
  term_key text not null unique,
  term text not null,
  term_type text not null default 'word',
  word_class text not null default 'unknown',
  meaning text,
  source text not null default 'conversation',
  provenance text not null default 'observed in owner conversation',
  confidence numeric not null default 0.5,
  status text not null default 'ACTIVE',
  times_seen int not null default 1,
  context text,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

ALTER TABLE public.frelux_vocabulary enable row level security;

GRANT ALL ON public.frelux_vocabulary TO service_role;
REVOKE ALL ON public.frelux_vocabulary FROM anon, authenticated;

